/* Recommendations remain drafts until the current profile explicitly adopts them. */
function personalGoalModel(){const report=currentBodyReport();if(!report)return null;const draft=coachDraft(report),rows=bodyRecords().filter(x=>reportDevice(x)===reportDevice(report)),end=today();function average(from,to){const dates=new Map();for(const x of rows)if(x.date>=from&&x.date<=to&&!dates.has(x.date))dates.set(x.date,x.weight);return {count:dates.size,value:dates.size?[...dates.values()].reduce((a,b)=>a+b,0)/dates.size:null}}const recent=average(shift(end,-6),end),previous=average(shift(end,-13),shift(end,-7)),change=recent.count>=3&&previous.count>=3?recent.value-previous.value:null;const stale=Date.parse(end)-Date.parse(report.date)>90*86400000;const days=data.training.weeklySplitActive?5:Number(draft.n.days);return {report,draft,recent,previous,change,stale,days,canApply:!!draft.plan&&draft.n.healthConfirmed&&!stale}}
function renderPersonalGoals(){const g=personalGoalModel();if(!g)return `<section class="card"><h2>أهداف مبنية على جسمك</h2><p>ابدأ برفع Excel أو إضافة قياس حديث، ثم أكّد العمر والطول والجنس والنشاط مرة واحدة.</p><button class="button" data-body-import>رفع سجل قياسات</button></section>`;const {report:m,draft:{n,plan,error}}=g,cut=n.goal==='تنشيف',bulk=n.goal==='تضخيم',signal=g.change==null?'سجّل الوزن في ٣ أيام على الأقل من كل أسبوع للمقارنة.':cut?(g.change<0?'اتجاه الوزن هابط. راقب القوة والتعافي بجانب الوزن.':'الوزن لم ينخفض هذا الأسبوع. راجع اكتمال تسجيل الوجبات والكميات قبل تعديل السعرات.'):bulk?(g.change>0?'الوزن يرتفع. تابع محيط الخصر وتقدم الأوزان لتقييم نوع الزيادة.':'الوزن لم يرتفع. راجع انتظام الوجبات والتدريب قبل زيادة السعرات.'):'قيّم محيط الخصر والأداء بجانب الوزن؛ الثبات لا ينفي تحسن تركيب الجسم.';return `<section class="card personal-goals"><div class="card-head"><div><p class="eyebrow">قرارك القادم</p><h2>${esc(n.goal)} · خطة متابعة شخصية</h2></div><button class="button secondary" data-coach="setup">تخصيص الهدف والبيانات</button></div><p class="sub">${esc(profileName())} · ${esc(reportDevice(m))} · ${pretty(m.date)} · ${fmt(m.weight)} كجم${m.bfr!=null?' · دهون '+fmt(m.bfr)+'%':''}</p>${plan?`<div class="body-metrics">${bodyMetric('الطاقة المقترحة',plan.targets.calories,'سعرة','الثبات التقديري '+fmt(plan.maintenance))}${bodyMetric('البروتين',plan.targets.protein,'غ','موزع على الوجبات')}${bodyMetric('كربوهيدرات',plan.targets.carbs,'غ','لدعم النشاط والتمرين')}${bodyMetric('دهون',plan.targets.fat,'غ','ضمن إجمالي الطاقة')}</div><div class="grid-two"><div><h3>ما الذي أفعله الآن؟</h3><ol><li>${cut?'التزم بعجز معتدل للطاقة مع تدريب مقاومة للحفاظ على العضلات.':bulk?'التزم بزيادة معتدلة للطاقة مع تحسن تدريجي في أداء المقاومة.':'ابدأ بطاقتك المقترحة وركز على تحسين القوة والعادات.'}</li><li>${g.days} أيام مقاومة أسبوعيًا حسب برنامجك${data.training.weeklySplitActive?'، الرجل الخميس والجمعة راحة':''}. سجّل العدات والوزن الفعلي.</li><li>اختر حملًا يترك ٢–٣ عدات ممكنة. زد بأصغر خطوة بعد إتقان أعلى العدات في جلستين.</li><li>افتح خطة التغذية لوجبات جاهزة قابلة للاستبدال؛ العشاء خفيف دون طبخ.</li></ol><a class="button secondary" href="#nutrition">وجباتي وكمياتي</a></div><div><h3>مراجعة أسبوعين</h3><p>${esc(signal)}</p><div class="goal-row"><span>متوسط آخر ٧ أيام</span><b>${g.recent.value==null?'—':fmt(g.recent.value)+' كجم'} (${g.recent.count} أيام)</b></div><div class="goal-row"><span>متوسط الأسبوع السابق</span><b>${g.previous.value==null?'—':fmt(g.previous.value)+' كجم'} (${g.previous.count} أيام)</b></div><div class="goal-row"><span>التغير</span><b>${g.change==null?'بيانات غير كافية':fmt(g.change)+' كجم'}</b></div><p class="sub">المقارنة من الجهاز نفسه، وقراءة واحدة لكل يوم. سجّل محيط الخصر أسبوعيًا وظروف القياس متشابهة. لا نغيّر السعرات تلقائيًا بسبب أسبوع واحد.</p></div></div><p class="notice">${g.stale?'القياس أقدم من ٩٠ يومًا: حدّثه قبل اعتماد الأهداف.':!n.healthConfirmed?'راجع البيانات الصحية والحساسيات والنشاط مرة واحدة لتفعيل اعتماد الأهداف.':'التوصيات تقديرية؛ تستطيع اعتمادها ثم تعديلها. اعتماد الأهداف يحافظ على وجباتك المعدلة وبرنامجك الحالي.'}</p><button class="button" data-adopt-goals ${g.canApply?'':'disabled'}>اعتماد أهداف الطاقة والماكروز والتمرين</button><p class="sub">هدف الوزن والماء والمشي يبقى قابلًا للتخصيص؛ لا نستنتج احتياج الماء من نسبة ماء الجسم، ولا نحدد وزنًا مثاليًا أو تمارين علاجية من InBody وحده.</p>`:`<p class="notice">${esc(error||'أكمل بياناتك لتجهيز الأهداف.')}</p>`}</section>`}
const settingsBeforeGoals=renderSettings;renderSettings=()=>renderPersonalGoals()+settingsBeforeGoals();
const bodyBeforeGoals=renderBodyCoach;renderBodyCoach=()=>renderPersonalGoals()+bodyBeforeGoals();
document.addEventListener('click',e=>{if(!e.target.closest('[data-adopt-goals]'))return;const g=personalGoalModel();if(!g?.canApply){notify('راجع معلوماتك واختر قياسًا حديثًا.',true);return}const next=structuredClone(data);Object.assign(next.targets,g.draft.plan.targets,{workoutDays:g.days});next.nutrition.goalRecommendation={reportId:g.report.id,source:reportDevice(g.report),reportDate:g.report.date,adoptedAt:new Date().toISOString(),goal:g.draft.n.goal};try{validate(next);commit(next,'تم اعتماد أهدافك؛ الوجبات والتمارين الحالية محفوظة')}catch(err){notify(err.message,true)}});
